Database: concert_singer
Schema:
CREATE TABLE stadium (Stadium_ID int PRIMARY KEY, Location text, Name text, Capacity int, Highest int, Lowest int, Average int);
CREATE TABLE singer (Singer_ID int PRIMARY KEY, Name text, Country text, Song_Name text, Song_release_year text, Age int, Is_male bool);
CREATE TABLE concert (concert_ID int PRIMARY KEY, concert_Name text, Theme text, Stadium_ID text, Year text, FOREIGN KEY (Stadium_ID) REFERENCES stadium(Stadium_ID));
CREATE TABLE singer_in_concert (concert_ID int, Singer_ID text, PRIMARY KEY (concert_ID,Singer_ID));
Question: How many singers do we have?
Target SQL: SELECT count(*) FROM singer

Database: concert_singer
Schema:
CREATE TABLE stadium (Stadium_ID int PRIMARY KEY, Location text, Name text, Capacity int, Highest int, Lowest int, Average int);
CREATE TABLE singer (Singer_ID int PRIMARY KEY, Name text, Country text, Song_Name text, Song_release_year text, Age int, Is_male bool);
CREATE TABLE concert (concert_ID int PRIMARY KEY, concert_Name text, Theme text, Stadium_ID text, Year text, FOREIGN KEY (Stadium_ID) REFERENCES stadium(Stadium_ID));
CREATE TABLE singer_in_concert (concert_ID int, Singer_ID text, PRIMARY KEY (concert_ID,Singer_ID));
Question: What are the names of stadiums that have held concerts in both 2014 and 2015?
Target SQL: SELECT T1.Name FROM stadium AS T1 JOIN concert AS T2 ON T1.Stadium_ID = T2.Stadium_ID WHERE T2.Year = '2014' INTERSECT SELECT T1.Name FROM stadium AS T1 JOIN concert AS T2 ON T1.Stadium_ID = T2.Stadium_ID WHERE T2.Year = '2015'

Database: flight_2
Schema:
CREATE TABLE airports (city text, airportcode text PRIMARY KEY, airportname text, country text, countryabbrev text);
CREATE TABLE airlines (airlineid int PRIMARY KEY, airlinename text, abbreviation text, country text);
CREATE TABLE flights (airline int, flightno int, sourceairport text, destairport text, PRIMARY KEY (airline, flightno));
Question: Find the count of flights departing from airport 'JFK'.
Target SQL: SELECT count(*) FROM flights WHERE sourceairport = 'JFK'

Database: academic
Schema:
CREATE TABLE author (aid int PRIMARY KEY, name text, oid int);
CREATE TABLE publication (pid int PRIMARY KEY, title text, year int, jid int);
CREATE TABLE writes (aid int, pid int, PRIMARY KEY (aid, pid));
CREATE TABLE domain_author (aid int, did int, PRIMARY KEY (aid, did));
CREATE TABLE domain (did int PRIMARY KEY, name text);
Question: Count publications published after 2020.
Target SQL: SELECT count(*) FROM publication WHERE year > 2020
